initiateHandshake(peerName: string): Buffer {
  const responderStaticKnown = this.trustedByName.get(peerName);
  if (!responderStaticKnown) throw new VpnError("UNKNOWN_PEER", `trustPeer("${peerName}", ...) was never called`);
  const ephemeral = generateX25519KeyPair();
  const initiatorReceiverId = randomUint32();
  const { message, dhSE } = buildHandshakeInit(initiatorReceiverId, this.staticPublicKey, ephemeral.privateKey, ephemeral.publicKeyRaw, responderStaticKnown);
  this.pendingHandshakes.set(initiatorReceiverId, { peerName, ephemeralPrivate: ephemeral.privateKey, ephemeralPublicRaw: ephemeral.publicKeyRaw, initiatorReceiverId, dhSE });
  return message;
}

