// real, src/replay-window.ts (trimmed)
check(counter: number): ReplayCheck {
  if (!Number.isInteger(counter) || counter < 0) return "TOO_OLD";
  if (counter <= this.highest - this.size) return "TOO_OLD"; // guards against stale-slot collision
  if (counter > this.highest) return "ACCEPT";
  return this.isSet(counter) ? "REPLAY" : "ACCEPT";
}
private isSet(counter: number): boolean {
  const bit = this.slot(counter);
  return (this.bitmap[bit >> 3]! & (1 << (bit & 7))) !== 0;
}

// real, src/peer.ts decryptPacket() (trimmed)
decryptPacket(data: Buffer): DecryptPacketResult {
  let fields;
  try { fields = decodeTransportData(data); } catch { return { ok: false, reason: "MALFORMED" }; }
  const entry = this.sessionsByReceiverId.get(fields.receiverId); // the exact dispatch step
  if (!entry) return { ok: false, reason: "UNKNOWN_SESSION" };
  const aad = transportAad(fields.receiverId, fields.counter);
  const result = entry.session.decrypt(fields.counter, fields.ciphertext, fields.tag, aad);
  if (!result.ok) return result;
  return { ok: true, peerName: entry.peerName, payload: result.payload };
}

// real, src/wire.ts (trimmed)
export function transportAad(receiverId: number, counter: number): Buffer {
  return Buffer.concat([uint32be(receiverId), uint64be(counter)]);
}

// real, src/replay-window.ts record() (trimmed)
record(counter: number): void {
  if (counter > this.highest) {
    const from = Math.max(this.highest + 1, counter - this.size + 1);
    for (let c = from; c <= counter; c++) this.clear(c); // bounded at `size` iterations
    this.highest = counter;
  }
  this.set(counter);
}

