import type { Peer } from "../src/peer.js";
import { decodeTransportData } from "../src/wire.js";

const SAFE_MARGIN = Number.MAX_SAFE_INTEGER * 0.01; // warn in the last 1% of safe range

export function encryptWithCounterWarning(peer: Peer, peerName: string, payload: Buffer): Buffer {
  const wire = peer.encryptPacket(peerName, payload);
  const { counter } = decodeTransportData(wire);
  if (Number.MAX_SAFE_INTEGER - counter < SAFE_MARGIN) {
    console.warn(`session with "${peerName}" is approaching the JS number precision limit at counter ${counter}`);
  }
  return wire;
}

