import { describe, expect, it } from "vitest";
import { trustedPeerPair } from "../test/helpers.js";

describe("tamper handling", () => {
  it("a tampered transport packet is dropped without throwing", () => {
    const { a: alice, b: bob } = trustedPeerPair("alice", "bob");
    const msg1 = alice.initiateHandshake("bob");
    const r1 = bob.receiveHandshakeInit(msg1);
    if (!r1.ok) throw new Error("setup failed");
    const r2 = alice.receiveHandshakeResponse(r1.response);
    if (!r2.ok) throw new Error("setup failed");

    const wire = Buffer.from(alice.encryptPacket("bob", Buffer.from("tamper target")));
    wire[wire.length - 1] = (wire[wire.length - 1]! ^ 0xff) & 0xff; // flip a tag byte

    expect(() => bob.decryptPacket(wire)).not.toThrow();
    expect(bob.decryptPacket(wire)).toEqual({ ok: false, reason: "AUTH_FAILED" });
  });
});

// real public API (hasSession) plus caller-maintained bookkeeping for the state Peer doesn't expose
import type { Peer } from "../src/peer.js";

export type PeerStatus = "handshaking" | "established" | "none";

export function peersStatus(
  peer: Peer,
  candidateNames: string[],
  handshaking: ReadonlySet<string>, // caller tracks this itself, from its own initiateHandshake calls
): Record<string, PeerStatus> {
  const result: Record<string, PeerStatus> = {};
  for (const name of candidateNames) {
    if (peer.hasSession(name)) result[name] = "established";
    else if (handshaking.has(name)) result[name] = "handshaking";
    else result[name] = "none";
  }
  return result;
}

// real public API (onDropped), illustrative tally wrapper
import type { VpnNode } from "../src/transport.js";

export interface DropTally {
  replay: number;
  authFailed: number;
  other: number;
}

export function trackDropReasons(node: VpnNode): DropTally {
  const tally: DropTally = { replay: 0, authFailed: 0, other: 0 };
  node.onDropped((reason) => {
    if (reason.includes("REPLAY")) tally.replay++;
    else if (reason.includes("AUTH_FAILED")) tally.authFailed++;
    else tally.other++;
  });
  return tally;
}

