// real public API (connect), illustrative retry wrapper
import type { VpnNode } from "../src/transport.js";

export async function connectWithRetry(
  node: VpnNode,
  peerName: string,
  host: string,
  port: number,
  maxAttempts = 3,
  baseDelayMs = 200,
): Promise<void> {
  let lastError: unknown;
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    try {
      await node.connect(peerName, host, port);
      return; // success
    } catch (err) {
      lastError = err;
      if (attempt < maxAttempts) {
        const delay = baseDelayMs * 2 ** (attempt - 1);
        await new Promise((resolve) => setTimeout(resolve, delay));
      }
    }
  }
  throw lastError;
}

